package com.johnny.hotel.cleaning;import com.johnny.hotel.common.Result;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/stays/{stayId}") @RequiredArgsConstructor @PreAuthorize("hasRole('CUSTOMER')") public class CustomerCleaningController {private final CleaningService service;private Long id(Authentication a){return(Long)a.getDetails();}@PostMapping("/cleaning-requests")public Result<StayoverCleaningRequest> request(@PathVariable Long stayId,@Valid @RequestBody CleaningRequests.Create r,Authentication a){return Result.success(service.requestStayover(stayId,r,id(a),true));}@GetMapping("/cleaning-records")public Result<com.johnny.hotel.pagination.PageResult<CleaningRecord>> history(@PathVariable Long stayId,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer pageSize,Authentication a){return Result.success(service.customerHistory(stayId,id(a),page,pageSize));}}
